describe('Snackbar Notification on Copy to Clipboard', () => {
  beforeEach(() => {
    cy.visit('/clipboard-test');
  });

  it('should display snackbar message after successfully copying text to clipboard', () => {
    // Verify clipboard button is visible
    cy.get('[data-testid="copy-button"]').should('be.visible');
    // Verify text area is visible and contains text
    cy.get('[data-testid="text-area"]').should('be.visible').should('have.length.greaterThan', 0);
    // Verify copy button is enabled
    cy.get('[data-testid="copy-button"]').should('not.be.disabled');
    // Click copy button
    cy.get('[data-testid="copy-button"]').click();
    // Wait for snackbar to appear
    cy.get('[data-testid="snackbar"]').should('be.visible');
    // Verify snackbar contains correct message
    cy.get('[data-testid="snackbar"]').should('contain', 'Text copied to clipboard');
    // Verify snackbar has success styling (e.g., green background)
    cy.get('[data-testid="snackbar"]').should('have.class', 'snackbar-success');
    // Verify snackbar auto-hides after a delay
    cy.get('[data-testid="snackbar"]').should('be.visible');
    cy.wait(3000);
    cy.get('[data-testid="snackbar"]').should('not.exist');
  });

  it('should not display snackbar when copy fails due to browser restrictions', () => {
    // Intercept clipboard API call to simulate failure
    cy.intercept('POST', '/api/clipboard/copy', {
      statusCode: 500,
      body: { error: 'Clipboard access denied' }
    }).as('copyFailure');
    // Click copy button
    cy.get('[data-testid="copy-button"]').click();
    // Wait for API call
    cy.wait('@copyFailure');
    // Verify snackbar does not appear
    cy.get('[data-testid="snackbar"]').should('not.exist');
    // Verify error message is displayed instead
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Failed to copy text');
    // Verify error has appropriate styling
    cy.get('[data-testid="error-message"]').should('have.class', 'error-text');
    // Verify copy button remains enabled for retry
    cy.get('[data-testid="copy-button"]').should('not.be.disabled');
  });
});
